--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,30 @@
 import type { ZoneRules } from "./zone.ts";
+import { parseZone, ZoneError } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  // Validate the zone name format
+  if (!name.match(/^[a-zA-Z_]+(\/[a-zA-Z0-9_+-]+)+$/)) {
+    throw new RangeError("Invalid zone name format");
+  }
+  
+  const url = `${ZONES_URL}/${name}`;
+  
+  try {
+    const response = await fetch(url);
+    
+    if (!response.ok) {
+      throw new ZoneError(`tz service unavailable: ${response.status} ${response.statusText}`);
+    }
+    
+    const body = await response.json();
+    return parseZone(body);
+  } catch (error) {
+    if (error instanceof ZoneError) {
+      throw error;
+    }
+    throw new ZoneError(`tz service unavailable: ${error instanceof Error ? error.message : 'Unknown error'}`);
+  }
 }
